package com.imageproc.pipeline

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.stream.ActorMaterializer
import scala.concurrent.{ExecutionContext, Future}
import scala.util.{Success, Failure}
import java.util.concurrent.atomic.AtomicBoolean
import java.nio.file.{Files, Paths, Path}
import javax.imageio.ImageIO
import java.awt.image.BufferedImage

object ImagePipelineServer extends App {

  implicit val system: ActorSystem = ActorSystem("image-pipeline")
  implicit val materializer: ActorMaterializer = ActorMaterializer()
  implicit val ec: ExecutionContext = system.dispatcher

  val shuttingDown = new AtomicBoolean(false)
  val processingQueue = new java.util.concurrent.ConcurrentLinkedQueue[String]()

  // Image metadata store - tracks processing status
  val metadataStore = new java.util.concurrent.ConcurrentHashMap[String, ImageMetadata]()

  case class ImageMetadata(
    filename: String,
    width: Int,
    height: Int,
    format: String,
    processingNote: String,
    statusCallback: String
  )

  // Sanitization layer for metadata display
  object HtmlEncoder {
    private val entityMap = Map(
      '&' -> "&amp;",
      '<' -> "&lt;",
      '>' -> "&gt;",
      '"' -> "&quot;"
    )

    def encode(input: String): String = {
      if (input == null) return ""
      input.flatMap(c => entityMap.getOrElse(c, c.toString))
    }

    // Encode for use in HTML attribute context
    def encodeAttr(input: String): String = {
      encode(input).replace("'", "&#x27;")
    }

    // Encode for use in JavaScript string context within HTML
    def encodeJsString(input: String): String = {
      if (input == null) return ""
      input
        .replace("\\", "\\\\")
        .replace("'", "\\'")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("/", "\\/")
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
    }
  }

  // Allowlist for callback URLs
  private val allowedCallbackHosts = Set("status.internal.example.com", "hooks.example.com")

  def validateCallback(url: String): Option[String] = {
    try {
      val parsed = new java.net.URL(url)
      if (parsed.getProtocol == "https" && allowedCallbackHosts.contains(parsed.getHost)) {
        Some(url)
      } else None
    } catch {
      case _: Exception => None
    }
  }

  def processImage(path: Path, callback: String): Future[ImageMetadata] = Future {
    val img: BufferedImage = ImageIO.read(path.toFile)
    val validatedCallback = validateCallback(callback).getOrElse("")
    val metadata = ImageMetadata(
      filename = path.getFileName.toString,
      width = img.getWidth,
      height = img.getHeight,
      format = path.getFileName.toString.split("\\.").lastOption.getOrElse("unknown"),
      processingNote = s"Processed at ${System.currentTimeMillis()}",
      statusCallback = validatedCallback
    )
    metadataStore.put(path.getFileName.toString, metadata)
    metadata
  }

  // Renders the status page - uses context-appropriate encoding
  def renderStatusPage(imageId: String): String = {
    val metadata = Option(metadataStore.get(imageId))
    metadata match {
      case Some(meta) =>
        val encodedFilename = HtmlEncoder.encode(meta.filename)
        val encodedNote = HtmlEncoder.encode(meta.processingNote)
        // The callback URL is encoded for JS string context then placed in script
        val encodedCallback = HtmlEncoder.encodeJsString(meta.statusCallback)
        s"""<!DOCTYPE html>
           |<html>
           |<head><title>Image Status: $encodedFilename</title></head>
           |<body>
           |  <h1>Processing Status</h1>
           |  <div class="metadata">
           |    <p>File: $encodedFilename</p>
           |    <p>Dimensions: ${meta.width}x${meta.height}</p>
           |    <p>Format: ${HtmlEncoder.encode(meta.format)}</p>
           |    <p>Note: $encodedNote</p>
           |  </div>
           |  <div id="callback-status"></div>
           |  <script>
           |    var callbackUrl = '$encodedCallback';
           |    fetch(callbackUrl).then(function(r) {
           |      document.getElementById('callback-status').innerText = 'Notified: ' + callbackUrl;
           |    });
           |  </script>
           |</body>
           |</html>""".stripMargin
      case None =>
        s"""<!DOCTYPE html>
           |<html><body><h1>Image not found</h1>
           |<p>No processing record for: ${HtmlEncoder.encode(imageId)}</p>
           |</body></html>""".stripMargin
    }
  }

  val route =
    path("process") {
      post {
        parameters("file", "callback") { (file, callback) =>
          if (shuttingDown.get()) {
            complete(StatusCodes.ServiceUnavailable, "Server shutting down")
          } else {
            val filePath = Paths.get("/uploads", file).normalize()
            if (!filePath.startsWith("/uploads")) {
              complete(StatusCodes.BadRequest, "Invalid path")
            } else {
              onComplete(processImage(filePath, callback)) {
                case Success(meta) =>
                  complete(StatusCodes.OK, s"Processed: ${meta.filename}")
                case Failure(ex) =>
                  complete(StatusCodes.InternalServerError, "Processing failed")
              }
            }
          }
        }
      }
    } ~
    path("status" / Segment) { imageId =>
      get {
        complete(HttpEntity(ContentTypes.`text/html(UTF-8)`, renderStatusPage(imageId)))
      }
    } ~
    path("health") {
      get {
        if (shuttingDown.get()) {
          complete(StatusCodes.ServiceUnavailable, "Shutting down")
        } else {
          complete(StatusCodes.OK, "Healthy")
        }
      }
    }

  val bindingFuture = Http().bindAndHandle(route, "0.0.0.0", 8080)

  // Graceful shutdown handler
  sys.addShutdownHook {
    shuttingDown.set(true)
    // Drain processing queue
    Thread.sleep(5000)
    bindingFuture
      .flatMap(_.unbind())
      .onComplete(_ => system.terminate())
  }

  println("Image pipeline server started on port 8080")
}
